export type supportChatSessionEvent =
  | { schemaVersion: "point.session.event.v1"; session: "support chat"; phase: "start"; at: number }
  | { schemaVersion: "point.session.event.v1"; session: "support chat"; phase: "chunk"; at: number; delta: string; content: string }
  | { schemaVersion: "point.session.event.v1"; session: "support chat"; phase: "complete"; at: number; ok: true }
  | { schemaVersion: "point.session.event.v1"; session: "support chat"; phase: "failure"; at: number; ok: false; error: { message: string } };

export type supportChatSessionState = { messages: ChatMessage[] };

export function supportChatSessionCreate(): supportChatSessionState {
  return { messages: [] };
}

export function supportChatSessionAddUserMessage(
  state: supportChatSessionState,
  content: string,
): supportChatSessionState {
  return {
    messages: [
      ...state.messages,
      { role: { kind: "User" }, content },
      { role: { kind: "Pending" }, content: "" },
    ],
  };
}

function supportChatApplyAssistantContent(state: supportChatSessionState, content: string): supportChatSessionState {
  const messages = [...state.messages];
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.role?.kind === "Pending") {
      messages[index] = { role: { kind: "Assistant" }, content };
      return { messages: messages };
    }
  }
  return { messages: [...messages, { role: { kind: "Assistant" }, content }] };
}

function supportChatUpdatePendingContent(state: supportChatSessionState, content: string): supportChatSessionState {
  const messages = [...state.messages];
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.role?.kind === "Pending") {
      messages[index] = { ...message, content };
      return { messages: messages };
    }
  }
  return state;
}

export async function* supportChatSessionStreamResponse(
  state: supportChatSessionState,
  prompt: Text,
  model: Text,
  __pointSessionLog?: PointSessionLog<supportChatSessionEvent> | null,
): AsyncGenerator<supportChatSessionEvent, supportChatSessionState, void> {
  const startEvent: supportChatSessionEvent = {
    schemaVersion: "point.session.event.v1",
    session: "support chat",
    phase: "start",
    at: pointSessionNow(),
  };
  pointSessionEmitLog(__pointSessionLog, startEvent);
  yield startEvent;
  const result = await summarizeSupportText(prompt, model);
  if (pointIsSessionError(result)) {
    const failureEvent: supportChatSessionEvent = {
      schemaVersion: "point.session.event.v1",
      session: "support chat",
      phase: "failure",
      at: pointSessionNow(),
      ok: false,
      error: { message: result.message },
    };
    pointSessionEmitLog(__pointSessionLog, failureEvent);
    yield failureEvent;
    return state;
  }
  let content = "";
  let current = state;
  for (const delta of pointSessionChunkText(result)) {
    content += delta;
    current = supportChatUpdatePendingContent(current, content)
    const chunkEvent: supportChatSessionEvent = {
      schemaVersion: "point.session.event.v1",
      session: "support chat",
      phase: "chunk",
      at: pointSessionNow(),
      delta,
      content,
    };
    pointSessionEmitLog(__pointSessionLog, chunkEvent);
    yield chunkEvent;
  }
  const finalState = supportChatApplyAssistantContent(current, content);
  const completeEvent: supportChatSessionEvent = {
    schemaVersion: "point.session.event.v1",
    session: "support chat",
    phase: "complete",
    at: pointSessionNow(),
    ok: true,
  };
  pointSessionEmitLog(__pointSessionLog, completeEvent);
  yield completeEvent;
  return finalState;
}


import { openaiStream as openaiStreamRaw } from "@hatchingpoint/point/std/ai";

import { envGet as envGetRaw } from "@hatchingpoint/point/std/env";

export type MessageRole = { kind: "Pending" } | { kind: "User" } | { kind: "Assistant" };

export interface ChatMessage {
  role: MessageRole;
  content: string;
}

export interface SupportContext {
  userName: string;
  tier: string;
}

export async function buildGreetingPrompt(context: SupportContext): Promise<string> {
  return (((("Hello " + context.userName) + ", thank you for contacting support. Your ") + context.tier) + " plan is ready to help.");
}

export async function summarizeSupportText(prompt: string, model: string): Promise<string | { message: string }> {
  return openaiStreamRaw(envGetRaw("OPENAI_API_KEY"), prompt, model);
}
